const raw = $json.body?.payload;

if (!raw) {
  throw new Error("No payload received from Slack");
}

const payload = JSON.parse(decodeURIComponent(raw));

const action = payload.actions?.[0];
const actionId = action?.action_id;
const actionValue = action?.value; // "isolate_{alert_id}_{host}"

// Parse value: isolate_SOC-2025-001_DESKTOP-ABC123
const parts = actionValue?.split("_") || [];
// parts[0] = "isolate", parts[1] = alert_id prefix, etc.
// Since alert_id itself contains dashes (SOC-2025-001), we need smarter parsing

const withoutPrefix = actionValue?.replace(/^(isolate_|unisolate_)/, "") || "";
// Now: "SOC-2025-001_DESKTOP-ABC123"
// Split on LAST underscore-separated segment that looks like a hostname
const lastUnderscore = withoutPrefix.lastIndexOf("_");
const alertId = withoutPrefix.substring(0, lastUnderscore);
const host = withoutPrefix.substring(lastUnderscore + 1);

return [{
  json: {
    action_id: actionId,
    alert_id: alertId,
    host: host,
    slack_user: payload.user?.name || payload.user?.id || "unknown",
    slack_user_id: payload.user?.id || "",
    channel_id: payload.channel?.id || "",
    message_ts: payload.message?.ts || "",        // needed to update original message
    response_url: payload.response_url || "",     // for updating message
    raw_payload: payload
  }
}];

